    'EncryptionDeleteBackupBodyWhat'        => 'Záloha uvnitř databáze bude okamžitě smazána. Už nebudete moci použít Obnovit ze zálohy k návratu databáze do stavu před šifrováním. Pokud později zjistíte problémy se šifrováním, jedinou cestou obnovy bude nová obnova databáze z vašich provozních záloh.',
