    'ControlIdOrShortNameFieldRequired' => 'Musí být namapováno buď pole ID kontroly, nebo pole Krátký název kontroly – řádek nelze identifikovat bez jednoho z nich.',
    'RiskImportSubjectNull' => 'ID rizika {$risk_id}: Nebylo aktualizováno, protože pole Předmět je prázdné nebo chybí.',
    'RiskImportSummary' => 'Odesláno rizik: {$submitted}, aktualizováno rizik: {$updated}.',
    'ControlImportSummary' => 'Vytvořeno kontrol: {$created}, aktualizováno kontrol: {$updated}.',
    'ImportAdditionalIssuesSuppressed' => 'Další řádky ({$count}) měly problémy, které se zde nezobrazují jednotlivě.',
    'EncryptionPipelineStalledTask' => 'Zdá se, že proces šifrování (úloha č. {$id}, {$type}) uvízl – po neobvykle dlouhou dobu má stav {$status} bez jakéhokoli postupu. Obvykle to znamená, že pracovní proces fronty na pozadí neběží; zkontrolujte, zda je naplánovaný, a poté zkuste znovu, až uvízlou úlohu zpracuje.',
    'EncryptionPipelineStalledState' => 'Zdá se, že proces šifrování uvízl – po neobvykle dlouhou dobu je označen jako probíhající, aniž by existovala odpovídající úloha na pozadí. Obvykle to znamená, že pracovní proces fronty neběží nebo předchozí proces skončil, aniž by tento stav správně aktualizoval. Před dalším pokusem zkontrolujte protokol ladění.',
    // DEMO_MODE — shown when a visitor to a shared demo instance attempts one
