    'RestoreTemplateConfirmBodyRisk' => 'Tímto se obnoví každé pole na kartách Podrobnosti, Zmírnění a Přezkoumání zpět na jeho výchozí hodnoty pro tuto skupinu šablon. Ostatní skupiny šablon nejsou ovlivněny.',
